<script setup lang="ts">
import {nextTick,ref,watch} from 'vue';import Icon from '../../shared/Icon.vue';
const props=defineProps<{open:boolean;picker:any;busy?:boolean}>();
const emit=defineEmits<{close:[];confirm:[documents:readonly any[]]}>();
const dialog=ref<HTMLDialogElement>();
watch(()=>props.open,open=>{if(open){void nextTick(async()=>{if(!dialog.value?.open)dialog.value?.showModal();if(!props.picker.opened.value)await props.picker.open();});}else dialog.value?.close();},{immediate:true});
function close(){dialog.value?.close();emit('close');}
function confirm(){emit('confirm',[...props.picker.selected.value]);}
function backdrop(event:MouseEvent){if(event.target===dialog.value)close();}
</script>
<template><dialog ref="dialog" class="mask material-picker-mask" role="presentation" @cancel.prevent="close" @click="backdrop"><div class="modal material-picker-modal" role="dialog" aria-modal="true" aria-label="从知识库选择背景材料"><div class="modal-h"><div><div class="m-t">从知识库选择背景材料</div><div class="small muted mt8">选择有权访问的文档版本，作为本次会议的背景材料。</div></div><button type="button" class="m-x" aria-label="关闭知识库选择" @click="close"><Icon name="x" :size="18"/></button></div><div class="modal-b material-picker-body"><div v-if="props.picker.libraryError.value||props.picker.error.value" class="ac-error" role="alert">{{props.picker.libraryError.value||props.picker.error.value}}</div><div class="material-picker-grid"><aside class="material-library-list"><div class="small muted mb8">知识库</div><button v-for="item in props.picker.libraries.value" :key="item.id" type="button" class="material-library-option" :class="{active:props.picker.library.value===item.id}" @click="props.picker.chooseLibrary(item.id)"><Icon name="layers" :size="16"/><span><b>{{item.name}}</b></span></button><div v-if="!props.picker.libraries.value.length&&!props.picker.libraryLoading.value" class="empty small">暂无有权限的知识库</div><div v-if="props.picker.libraryLoading.value" class="small muted">加载知识库中…</div></aside><section class="material-document-list"><div class="between mb12"><b>{{props.picker.review.value?'已选文件':'文件'}}</b><input v-if="!props.picker.review.value" v-model="props.picker.query.value" class="input material-search" aria-label="搜索知识库文件" placeholder="搜索文件名称" @input="props.picker.search(props.picker.query.value)"/></div><div v-if="props.picker.loading.value" class="empty">正在加载文件…</div><label v-for="doc in (props.picker.review.value?props.picker.selected.value:props.picker.documents.value)" v-else :key="props.picker.knowledgeKey?props.picker.knowledgeKey(doc):doc.id+doc.version" class="material-document-row"><input type="checkbox" :checked="props.picker.selected.value.some((x:any)=>x.id===doc.id&&x.version===doc.version)" :disabled="props.busy" @change="props.picker.toggle(doc)"/><span><b :title="doc.name">{{doc.name}}</b><small>{{doc.name.split('.').pop()?.toUpperCase()}} · 版本 {{doc.version.slice(0,12)}} · {{doc.sizeBytesToken}} B</small></span></label><div v-if="!props.picker.loading.value&&!((props.picker.review.value?props.picker.selected.value:props.picker.documents.value).length)" class="empty">{{props.picker.library.value?'当前知识库暂无文件':'请选择知识库'}}</div><button v-if="!props.picker.review.value&&props.picker.cursor.value" type="button" class="btn sm" @click="props.picker.moreDocuments()">加载更多</button></section></div><div class="material-picker-selection small muted" role="status">已选择 {{props.picker.selected.value.length}} 个文件</div></div><div class="modal-f"><button type="button" class="btn" :disabled="props.busy" @click="close">取消</button><button type="button" class="btn primary" :disabled="props.busy||!props.picker.selected.value.length" @click="confirm">添加到会议</button></div></div></dialog></template>
<style scoped>.material-picker-mask{inset:0;width:auto;height:auto;max-width:none;max-height:none;padding:0;margin:0;border:0;overflow:visible}.material-picker-mask:not([open]){display:none}.material-picker-mask::backdrop{background:transparent}.material-picker-modal{width:860px;max-width:calc(100vw - 40px);max-height:86vh}.material-picker-body{min-height:360px}.material-picker-grid{display:grid;grid-template-columns:220px minmax(0,1fr);border:1px solid var(--border);border-radius:8px;min-height:330px;overflow:hidden}.material-library-list{padding:16px;border-right:1px solid var(--border);background:#FCFCFA}.material-library-option{display:flex;align-items:center;gap:8px;width:100%;text-align:left;border:0;background:transparent;border-radius:7px;padding:9px 8px;cursor:pointer;color:var(--text)}.material-library-option.active{background:#fff1e8;color:var(--orange)}.material-document-list{padding:16px;min-width:0}.material-search{max-width:230px}.material-document-row{display:flex;align-items:flex-start;gap:10px;padding:11px 4px;border-bottom:1px solid var(--border);cursor:pointer}.material-document-row span{display:flex;flex-direction:column;gap:4px;min-width:0}.material-document-row b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.material-document-row small{color:var(--muted)}.material-picker-selection{margin-top:12px}@media(max-width:700px){.material-picker-grid{grid-template-columns:1fr}.material-library-list{border-right:0;border-bottom:1px solid var(--border)}}
</style>
